  'commits0': projects.filter(p => !p.commit_count || p.commit_count === 0).length,
  'commits1-5': projects.filter(p => p.commit_count && p.commit_count >= 1 && p.commit_count <= 5).length,
  'commits6-20': projects.filter(p => p.commit_count && p.commit_count >= 6 && p.commit_count <= 20).length,
  'commits20+': projects.filter(p => p.commit_count && p.commit_count > 20).length,
};

