console.log('🔍 전체 저장소 커밋 수 수집 (이 작업은 시간이 걸립니다)\n');

const results = [];
let count = 0;

for (let i = 0; i < Math.min(20, withRepo.length); i++) {  // 처음 20개만
  const proj = withRepo[i];
  count++;

  process.stdout.write(`[${count}/${Math.min(20, withRepo.length)}] ${proj.name}... `);

  try {
    const tempDir = `/tmp/commit-check-${i}`;
    execSync(`rm -rf "${tempDir}" 2>/dev/null; git clone --quiet "${proj.repo_url}" "${tempDir}"`, { stdio: 'ignore', timeout: 30000 });

    const actual = execSync(`cd "${tempDir}" && git log --oneline | wc -l`, { encoding: 'utf-8' }).trim();
    execSync(`rm -rf "${tempDir}"`, { stdio: 'ignore' });

    const meta = proj.commit_count || 0;
    const diff = parseInt(actual) - meta;

    results.push({
      name: proj.name,
      meta,
      actual: parseInt(actual),
      diff,
      loss: Math.round((Math.abs(diff) / parseInt(actual)) * 100) + '%'
    });

    console.log(`메타:${meta} 실제:${actual} (${diff > 0 ? '+' : ''}${diff})`);
  } catch (e) {
    console.log('❌ 실패');
  }
}

