const avgLoss = results.filter(r => r.actual > r.meta).reduce((s, r) => s + (Math.abs(r.diff) / r.actual * 100), 0) / results.length;

console.log('평균 차이: ' + avgDiff.toFixed(1) + ' commits');
console.log('평균 손실: ' + avgLoss.toFixed(1) + '%');

console.log('\n손실이 큰 프로젝트 (상위 5):');
results.sort((a,b) => Math.abs(b.diff) - Math.abs(a.diff)).slice(0, 5).forEach(r => {
  console.log(`  ${r.name}: 메타 ${r.meta} → 실제 ${r.actual} (${r.loss} 손실)`);
});
EOF

