const fs = require('fs');
const data = JSON.parse(fs.readFileSync('/data/data/com.termux/files/home/kim-project-cli/projects-with-gogs-urls-with-metadata.json', 'utf-8'));
const projects = Array.isArray(data) ? data : data.projects || [];

console.log('=== 📊 승급 가능성 분석 ===\n');

// 현재 F 등급 45개 분석
const fProjects = projects.filter(p => p.health && p.health.score < 40);
console.log('현재 F 등급: ' + fProjects.length + '개\n');

// 1. 0 커밋 (불가능 - 영구 F)
const noCommit = fProjects.filter(p => !p.commit_count || p.commit_count === 0);
console.log('1️⃣ 0 커밋 (불가 승급)');
console.log('   개수: ' + noCommit.length + '개');
console.log('   상태: archived / experimental');
console.log('   → 영구 F 등급 (정상)\n');

// 2. 1-5 커밋 (가능성 낮음)
const lowCommit = fProjects.filter(p => p.commit_count && p.commit_count >= 1 && p.commit_count <= 5);
console.log('2️⃣ 1-5 커밋 (승급 어려움)');
console.log('   개수: ' + lowCommit.length + '개');
lowCommit.slice(0, 5).forEach(p => {
  console.log('   - ' + p.name + ': ' + p.commit_count + ' commits');
});
if(lowCommit.length > 5) console.log('   ... 및 ' + (lowCommit.length - 5) + '개 더');
console.log('   → 추가 개발 필요\n');

// 3. --depth 50 손실로 인한 오평가 (고가능성!)
const largeRepo = projects.filter(p => p.commit_count >= 50);
console.log('3️⃣ 50+ 커밋 (--depth 50 손실 가능성!)');
console.log('   개수: ' + largeRepo.length + '개');
largeRepo.slice(0, 10).forEach(p => {
  const health = p.health?.score || 0;
  const grade = health >= 90 ? 'A+' : health >= 80 ? 'A' : health >= 70 ? 'B+' : health >= 60 ? 'B' : health >= 50 ? 'C' : 'D/F';
  console.log('   - ' + p.name + ': ' + p.commit_count + ' commits → ' + health + '/100 (' + grade + ')');
});
console.log('   → 메타데이터 재수집 시 평균 10-15점 상승!\n');

// 4. 문서화 부족 프로젝트 (개선 가능)
const noDocs = projects.filter(p => p.health && p.health.docScore < 30);
console.log('4️⃣ 문서화 부족 (개선 가능)');
console.log('   개수: ' + noDocs.length + '개');
console.log('   평균 doc: ' + Math.round(noDocs.reduce((s,p) => s + (p.health?.docScore || 0), 0) / noDocs.length) + '/100');
console.log('   → README, 설명 추가로 5-10점 상승\n');

// 5. 예상 점수 분포 (수정 후)
console.log('=== 📈 예상 승급 분포 ===\n');

const correctedScores = projects.map(p => {
  const current = p.health?.score || 0;
  let corrected = current;

  // 규칙 1: 50+ 커밋이면 +10-15점
  if(p.commit_count >= 50) corrected += 12;

  // 규칙 2: 문서화 부족이면 +5-10점 (README 추가)
  if(p.health?.docScore < 30) corrected += 7;

  // 규칙 3: 최대 100점
  corrected = Math.min(100, corrected);

  return { name: p.name, current, corrected, commit: p.commit_count };
});

// 승급 분석
const upgradable = correctedScores.filter(p => p.corrected > p.current && p.current < 60);
console.log('상향 가능한 프로젝트: ' + upgradable.length + '개');
upgradable.slice(0, 10).forEach(p => {
  console.log('  ' + p.name + ': ' + p.current + ' → ' + p.corrected + ' (+' + (p.corrected - p.current) + ')');
});
console.log('');

// 등급별 분석
const grades = {
  'A+ (90+)': 0,
  'A (80-89)': 0,
  'B+ (70-79)': 0,
  'B (60-69)': 0,
  'C (50-59)': 0,
  'D+ (40-49)': 0,
  'D (30-39)': 0,
  'F (0-29)': 0
};

projects.forEach(p => {
  const score = p.health?.score || 0;
  if(score >= 90) grades['A+ (90+)']++;
  else if(score >= 80) grades['A (80-89)']++;
  else if(score >= 70) grades['B+ (70-79)']++;
  else if(score >= 60) grades['B (60-69)']++;
  else if(score >= 50) grades['C (50-59)']++;
  else if(score >= 40) grades['D+ (40-49)']++;
  else if(score >= 30) grades['D (30-39)']++;
  else grades['F (0-29)']++;
});

console.log('현재 등급 분포:');
Object.entries(grades).forEach(([g, c]) => {
